<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('charity');$pdo=db();$charityId=(int)$user['charity_id'];
if(is_post()){verify_csrf();$id=(int)($_POST['request_id']??0);$action=$_POST['action']??'';if(!in_array($action,['close','reopen'],true)){http_response_code(400);exit('Invalid action.');}$stmt=$pdo->prepare('UPDATE clothing_requests SET status=? WHERE id=? AND charity_id=?');$stmt->execute([$action==='close'?'closed':'active',$id,$charityId]);if($stmt->rowCount()){log_activity($pdo,$action==='close'?'closed a clothing request':'reopened a clothing request',(int)$user['id'],'request',$id);flash('success','Request '.($action==='close'?'closed':'reopened').'.');}else flash('error','We could not change that request.');redirect('charity/requests.php');}
$stmt=$pdo->prepare("SELECT cr.*,COALESCE((SELECT SUM(quantity_needed) FROM request_requirements WHERE request_id=cr.id),0) needed,COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id JOIN request_requirements rr ON rr.id=di.request_requirement_id WHERE rr.request_id=cr.id AND dp.status='received'),0) received,COUNT(DISTINCT dp.id) pledges FROM clothing_requests cr LEFT JOIN donation_pledges dp ON dp.request_id=cr.id WHERE cr.charity_id=? GROUP BY cr.id ORDER BY cr.created_at DESC");$stmt->execute([$charityId]);$requests=$stmt->fetchAll();$pageTitle='Manage requests';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">Your published needs</span><h1>Clothing requests</h1><p>Keep each ask clear, current, and useful for donors.</p></div><a class="button" href="<?=e(url('charity/request_form.php'))?>">Post a clothing need +</a></div><div class="panel"><?php if(!$requests):?><div class="empty"><span class="empty-icon">◫</span>No requests yet. Your community is ready when you are.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Need / received</th><th>Pledges</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['location'])?> · <?=e($r['season'])?></span></td><td><?=$r['needed']?> / <?=$r['received']?></td><td><?=$r['pledges']?></td><td><span class="status <?=e(status_class($r['status']))?>"><?=e($r['status'])?></span></td><td class="row-actions"><a class="button button-small button-outline" href="<?=e(url('charity/request_form.php?id='.$r['id']))?>">Edit</a><form method="post" data-loading data-confirm="<?= $r['status']==='active'?'Close this request? New pledges will stop.':'Reopen this request to donors?' ?>"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$r['status']==='active'?'close':'reopen'?>"><button class="button button-small <?= $r['status']==='active'?'button-danger':'button-sun'?>" type="submit"><?=$r['status']==='active'?'Close':'Reopen'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
